# 폐허 마을 조각 메타(partmeta.json 으로 저장, 굽는 스크립트가 읽는다). 키 = 조각 파일 이름(확장자 없이).
def M(kind, ko, desc, rules, brows=None, layer=None, role=None):
    d = dict(kind=kind, ko=ko, desc=desc, rules=rules)
    if brows is not None: d['brows'] = brows
    if layer: d['layer'] = layer
    if role: d['role'] = role
    return d

